const express = require('express');
const { sessionAuth } = require('../auth');
const { searchClient } = require('../services/search');

const app = express();
app.use(express.json());

app.post('/api/search/documents', sessionAuth, async (req, res) => {
  const { query, requestedWorkspaceId } = req.body;

  // Use caller's verified default workspace or ensure requestedWorkspaceId is in authorized workspaces
  const targetWorkspace = requestedWorkspaceId || req.user.defaultWorkspaceId;
  if (!req.user.authorizedWorkspaces?.includes(targetWorkspace)) {
    return res.status(403).json({ error: 'Access denied to target workspace' });
  }

  const hits = await searchClient.search({
    index: 'corporate_documents',
    query: {
      bool: {
        must: [{ match: { text: query } }],
        filter: [{ term: { workspaceId: targetWorkspace } }]
      }
    }
  });

  res.json({ workspaceId: targetWorkspace, results: hits });
});

module.exports = app;
